import hourglass.models
import hourglass.parsing


def check_step(step):
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError("step must be a positive whole number of minutes dividing an hour: {!r}".format(step))


def round_minutes(minutes, step):
    check_step(step)
    return (2 * minutes + step) // (2 * step) * step


# ---
def round_span(span, step):
    return hourglass.models.Span(round_minutes(span.start, step), round_minutes(span.end, step))


# ---
def span_labels(spans, step):
    check_step(step)
    labels = []
    for span in spans:
        rounded = round_span(span, step)
        hours, minutes = divmod(rounded.minutes, 60)
        labels.append("{} ({}h {}m)".format(hourglass.parsing.format_span(rounded), hours, minutes))
    return labels
