import unittest

import hourglass.models
import hourglass.rounding


class SpanLabelTests(unittest.TestCase):
    def test_label_for_exact_span(self):
        spans = [hourglass.models.Span(9 * 60, 17 * 60 + 15)]
        self.assertEqual(hourglass.rounding.span_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest_step(self):
        spans = [hourglass.models.Span(9 * 60 + 6, 17 * 60 + 8), hourglass.models.Span(60 + 7, 120 + 8)]
        self.assertEqual(
            hourglass.rounding.span_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "01:00-02:15 (1h 15m)"],
        )

    def test_halfway_rounds_up(self):
        spans = [hourglass.models.Span(7 * 60 + 30, 9 * 60)]
        self.assertEqual(hourglass.rounding.span_labels(spans, 60), ["08:00-09:00 (1h 0m)"])

    def test_end_of_day(self):
        spans = [hourglass.models.Span(22 * 60, 24 * 60 - 2)]
        self.assertEqual(hourglass.rounding.span_labels(spans, 5), ["22:00-24:00 (2h 0m)"])

    def test_empty_list(self):
        self.assertEqual(hourglass.rounding.span_labels([], 15), [])

    def test_span_that_collapses_is_rejected(self):
        with self.assertRaises(ValueError):
            hourglass.rounding.span_labels([hourglass.models.Span(542, 545)], 15)


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [hourglass.models.Span(0, 60)]
        for step in (0, -15, 7, 45, 90, 1.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    hourglass.rounding.span_labels(spans, step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            hourglass.rounding.span_labels([], 0)

    def test_good_steps(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(hourglass.rounding.round_minutes(100, step) % step, 0)
